import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"全文搜索","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/advanced/search.md","filePath":"zh-CN/advanced/search.md","lastUpdated":1784903584000}'),n={name:"zh-CN/advanced/search.md"};function o(p,t,l,c,i,r){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="全文搜索" tabindex="-1">全文搜索 <a class="header-anchor" href="#全文搜索" aria-label="Permalink to &quot;全文搜索&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>swag2mcp 包含一个内置的全文搜索引擎（bluge），用于索引所有 spec 中的所有端点。LLM 可以按方法、路径、摘要或标签搜索端点 — 即使不知道端点 ID。</p><h2 id="索引工作原理" tabindex="-1">索引工作原理 <a class="header-anchor" href="#索引工作原理" aria-label="Permalink to &quot;索引工作原理&quot;">​</a></h2><p>当添加或更新 spec 时，每个端点都会被索引。以下字段可搜索：</p><table tabindex="0"><thead><tr><th>字段</th><th>描述</th><th>示例</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP 方法</td><td><code>GET</code>、<code>POST</code>、<code>PUT</code></td></tr><tr><td><code>path</code></td><td>API 端点路径</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>OpenAPI 摘要</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>端点类别</td><td>&quot;pets&quot;、&quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>所有字段组合</td><td>method + path + tag + summary</td></tr></tbody></table><p>索引在每次 MCP 服务器启动时重建。它存储在内存中以实现快速搜索。</p><h2 id="查询语法" tabindex="-1">查询语法 <a class="header-anchor" href="#查询语法" aria-label="Permalink to &quot;查询语法&quot;">​</a></h2><p>搜索支持丰富的查询语法，用于精确过滤：</p><table tabindex="0"><thead><tr><th>示例</th><th>描述</th></tr></thead><tbody><tr><td><code>pet</code></td><td>跨所有字段的简单文本搜索</td></tr><tr><td><code>method:GET</code></td><td>查找所有 GET 端点</td></tr><tr><td><code>tag:pets</code></td><td>查找 &quot;pets&quot; 标签中的端点</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>精确路径匹配</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>必须匹配两个条件</td></tr><tr><td><code>-method:DELETE</code></td><td>排除 DELETE 方法</td></tr><tr><td><code>create~</code></td><td>模糊搜索（容错）</td></tr><tr><td><code>cr*</code></td><td>通配符搜索</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>短语搜索</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>摘要中包含 &quot;pet&quot;，排除 DELETE</td></tr></tbody></table><h3 id="字段特定搜索" tabindex="-1">字段特定搜索 <a class="header-anchor" href="#字段特定搜索" aria-label="Permalink to &quot;字段特定搜索&quot;">​</a></h3><p>你可以使用 <code>field:value</code> 语法在特定字段内搜索：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="布尔运算符" tabindex="-1">布尔运算符 <a class="header-anchor" href="#布尔运算符" aria-label="Permalink to &quot;布尔运算符&quot;">​</a></h3><ul><li><code>+</code> — 必须匹配（AND）</li><li><code>-</code> — 必须不匹配（NOT）</li><li>术语之间的空格 — OR（任何术语可以匹配）</li></ul><h3 id="模糊和通配符" tabindex="-1">模糊和通配符 <a class="header-anchor" href="#模糊和通配符" aria-label="Permalink to &quot;模糊和通配符&quot;">​</a></h3><ul><li><code>term~</code> — 模糊搜索（匹配相似单词，处理拼写错误）</li><li><code>te*</code> — 通配符（匹配任意字符）</li><li><code>te?t</code> — 单字符通配符</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 查找所有 GET 请求</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查找 pet 标签中的 POST 请求</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 按精确路径查找端点</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 按描述查找</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查找除 DELETE 之外的所有内容</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># &quot;create&quot; 的模糊搜索（处理拼写错误）</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-工具" tabindex="-1">MCP 工具 <a class="header-anchor" href="#mcp-工具" aria-label="Permalink to &quot;MCP 工具&quot;">​</a></h2><p><code>search</code> MCP 工具将搜索引擎暴露给 LLM：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Finds Pets by status</span></span>
<span class="line"><span>   GET /pet/{petId} — Find pet by ID</span></span></code></pre></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>描述</th></tr></thead><tbody><tr><td><code>query</code></td><td>是</td><td>搜索查询（支持结构化语法）</td></tr><tr><td><code>limit</code></td><td>是</td><td>最大结果数（1-50）</td></tr></tbody></table><h2 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h2><ul><li><strong>索引在内存中</strong> — 每次 MCP 服务器启动时重建。没有持久的索引文件。</li><li><strong>所有字段小写</strong> — 搜索不区分大小写</li><li><strong>限制上限为 50</strong> — 你不能请求超过 50 个结果</li><li><strong>无效的查询语法</strong> 返回带有示例的帮助性错误消息</li><li><strong><code>_all</code> 字段</strong> 组合 method、path、tag 和 summary 用于简单文本搜索</li></ul>`,26)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
